1	import { Hono } from "hono";
2	
3	/**
4	 * First-run setup Hono app.
5	 *
6	 * Served at `/setup` before `SETUP_COMPLETED` is set in KV. Collects the
7	 * secrets and credentials needed to run Paperclip and stores them in KV /
8	 * the `instance_settings` DB table. Once setup completes, all Workers read
9	 * config from the DB (encrypted with a master key stored as a Worker secret).
10	 *
11	 * Fields collected:
12	 *   - LLM API key (Anthropic and/or OpenAI)
13	 *   - Neon/Postgres connection string (Hyperdrive Phase 1)
14	 *   - Operator email and initial password
15	 *   - Optional: sandbox bridge URL and API key (for plugin execution)
16	 *
17	 * Security: this route is gated — it only accepts requests when
18	 * `SETUP_COMPLETED` is absent from KV (enforced by the middleware in
19	 * `api.ts`). After setup completes it permanently locks itself.
20	 */
21	
22	interface SetupEnv {
23	  PAPERCLIP_KV: KVNamespace;
24	  HYPERDRIVE?: { connectionString: string };
25	}
26	
27	interface SetupFormData {
28	  anthropicApiKey?: string;
29	  openaiApiKey?: string;
30	  neonConnectionString?: string;
31	  operatorEmail: string;
32	  operatorPassword: string;
33	  sandboxBridgeUrl?: string;
34	  sandboxBridgeApiKey?: string;
35	}
36	
37	interface ValidationErrors {
38	  [field: string]: string;
39	}
40	
41	function validateSetupForm(data: SetupFormData): ValidationErrors {
42	  const errors: ValidationErrors = {};
43	
44	  if (!data.operatorEmail || !data.operatorEmail.includes("@")) {
45	    errors.operatorEmail = "A valid email address is required.";
46	  }
47	  if (!data.operatorPassword || data.operatorPassword.length < 12) {
48	    errors.operatorPassword = "Password must be at least 12 characters.";
49	  }
50	  if (!data.anthropicApiKey && !data.openaiApiKey) {
51	    errors.llmKey = "At least one LLM API key (Anthropic or OpenAI) is required.";
52	  }
53	
54	  return errors;
55	}
56	
57	function setupHtml(opts: {
58	  errors?: ValidationErrors;
59	  prefill?: Partial<SetupFormData>;
60	  success?: boolean;
61	}): string {
62	  const { errors = {}, prefill = {}, success = false } = opts;
63	
64	  if (success) {
65	    return `<!DOCTYPE html>
66	<html lang="en">
67	<head>
68	  <meta charset="UTF-8">
69	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
70	  <title>Paperclip — Setup Complete</title>
71	  <style>
72	    body { font-family: system-ui, sans-serif; max-width: 560px; margin: 80px auto; padding: 0 24px; }
73	    .card { background: #f9fafb; border: 1px solid #e5e7eb; border-radius: 8px; padding: 32px; }
74	    h1 { font-size: 1.5rem; margin-bottom: 8px; }
75	    p { color: #374151; line-height: 1.6; }
76	    a { color: #2563eb; }
77	  </style>
78	</head>
79	<body>
80	  <div class="card">
81	    <h1>Setup complete</h1>
82	    <p>Your Paperclip instance is ready. <a href="/">Open the dashboard</a> to get started.</p>
83	    <p>Sign in with the operator email and password you just configured.</p>
84	  </div>
85	</body>
86	</html>`;
87	  }
88	
89	  const field = (
90	    name: keyof SetupFormData,
91	    label: string,
92	    type = "text",
93	    placeholder = "",
94	    required = false,
95	  ) => {
96	    const error = errors[name];
97	    const value = prefill[name] ?? "";
98	    return `
99	    <div class="field${error ? " field--error" : ""}">
100	      <label for="${name}">${label}${required ? " <span aria-hidden='true'>*</span>" : ""}</label>
101	      <input
102	        id="${name}"
103	        name="${name}"
104	        type="${type}"
105	        placeholder="${placeholder}"
106	        value="${String(value).replace(/"/g, "&quot;")}"
107	        ${required ? "required" : ""}
108	      />
109	      ${error ? `<span class="error-msg">${error}</span>` : ""}
110	    </div>`;
111	  };
112	
113	  const llmError = errors.llmKey ?? "";
114	
115	  return `<!DOCTYPE html>
116	<html lang="en">
117	<head>
118	  <meta charset="UTF-8">
119	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
120	  <title>Paperclip — First-run Setup</title>
121	  <style>
122	    *, *::before, *::after { box-sizing: border-box; }
123	    body { font-family: system-ui, sans-serif; max-width: 560px; margin: 48px auto; padding: 0 24px; color: #111; }
124	    h1 { font-size: 1.6rem; }
125	    p.lead { color: #374151; margin-bottom: 32px; }
126	    .card { background: #f9fafb; border: 1px solid #e5e7eb; border-radius: 8px; padding: 32px; }
127	    h2 { font-size: 1rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em;
128	         color: #6b7280; margin: 24px 0 12px; }
129	    h2:first-child { margin-top: 0; }
130	    .field { display: flex; flex-direction: column; gap: 4px; margin-bottom: 16px; }
131	    label { font-size: 0.875rem; font-weight: 500; }
132	    input { padding: 8px 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 0.9375rem;
133	            width: 100%; }
134	    input:focus { outline: none; border-color: #2563eb; box-shadow: 0 0 0 2px rgba(37,99,235,0.15); }
135	    .field--error input { border-color: #dc2626; }
136	    .error-msg { color: #dc2626; font-size: 0.8125rem; }
137	    .llm-error { color: #dc2626; font-size: 0.8125rem; margin-top: -8px; margin-bottom: 16px; }
138	    small { color: #6b7280; font-size: 0.8125rem; }
139	    button[type=submit] {
140	      width: 100%; padding: 10px 16px; background: #2563eb; color: #fff;
141	      border: none; border-radius: 6px; font-size: 1rem; font-weight: 600;
142	      cursor: pointer; margin-top: 8px;
143	    }
144	    button[type=submit]:hover { background: #1d4ed8; }
145	  </style>
146	</head>
147	<body>
148	  <h1>Paperclip Setup</h1>
149	  <p class="lead">
150	    Complete the form below to configure your Paperclip instance.
151	    You only need to do this once.
152	  </p>
153	  <div class="card">
154	    <form method="POST" action="/setup">
155	
156	      <h2>Admin account</h2>
157	      ${field("operatorEmail", "Email address", "email", "admin@example.com", true)}
158	      ${field("operatorPassword", "Password (min. 12 characters)", "password", "", true)}
159	
160	      <h2>LLM provider keys</h2>
161	      <small>At least one key is required. Keys are stored encrypted in the database.</small>
162	      ${llmError ? `<p class="llm-error">${llmError}</p>` : ""}
163	      ${field("anthropicApiKey", "Anthropic API key", "password", "sk-ant-...")}
164	      ${field("openaiApiKey", "OpenAI API key", "password", "sk-...")}
165	
166	      <h2>Database (Phase 1 — Hyperdrive)</h2>
167	      <small>
168	        Create a free Neon Postgres database at <a href="https://neon.tech" target="_blank">neon.tech</a>,
169	        then run <code>wrangler hyperdrive create paperclip-hyperdrive --connection-string="&lt;url&gt;"</code>
170	        and paste the Hyperdrive ID in your <code>wrangler.toml</code>.
171	        Leave blank to skip (you can set this later via wrangler).
172	      </small>
173	      ${field("neonConnectionString", "Neon connection string (optional)", "password", "postgres://...")}
174	
175	      <h2>Sandbox bridge (optional)</h2>
176	      <small>
177	        Required for plugin execution. Set up the E2B or SSH sandbox bridge and provide
178	        its URL and API key here. See
179	        <a href="https://github.com/paperclipai/paperclip/blob/master/doc/CLOUDFLARE.md" target="_blank">
180	          CLOUDFLARE.md
181	        </a> for instructions.
182	      </small>
183	      ${field("sandboxBridgeUrl", "Sandbox bridge URL", "url", "https://bridge.example.com")}
184	      ${field("sandboxBridgeApiKey", "Sandbox bridge API key", "password")}
185	
186	      <button type="submit">Complete setup</button>
187	    </form>
188	  </div>
189	</body>
190	</html>`;
191	}
192	
193	/**
194	 * Creates the `/setup` Hono sub-application.
195	 *
196	 * Mount it under the main app:
197	 * ```ts
198	 * app.route("/setup", createSetupApp(env));
199	 * ```
200	 */
201	export function createSetupApp(env: SetupEnv): Hono {
202	  const setup = new Hono();
203	
204	  // GET /setup — render the setup form
205	  setup.get("/", (c) => c.html(setupHtml({})));
206	
207	  // POST /setup — process the form submission
208	  setup.post("/", async (c) => {
209	    const body = await c.req.parseBody();
210	
211	    const data: SetupFormData = {
212	      anthropicApiKey: String(body.anthropicApiKey ?? "").trim() || undefined,
213	      openaiApiKey: String(body.openaiApiKey ?? "").trim() || undefined,
214	      neonConnectionString: String(body.neonConnectionString ?? "").trim() || undefined,
215	      operatorEmail: String(body.operatorEmail ?? "").trim(),
216	      operatorPassword: String(body.operatorPassword ?? ""),
217	      sandboxBridgeUrl: String(body.sandboxBridgeUrl ?? "").trim() || undefined,
218	      sandboxBridgeApiKey: String(body.sandboxBridgeApiKey ?? "").trim() || undefined,
219	    };
220	
221	    const errors = validateSetupForm(data);
222	    if (Object.keys(errors).length > 0) {
223	      return c.html(
224	        setupHtml({ errors, prefill: { ...data, operatorPassword: "" } }),
225	        400,
226	      );
227	    }
228	
229	    try {
230	      // Persist non-secret config to KV (plain strings)
231	      const kvWrites: Array<Promise<void>> = [
232	        env.PAPERCLIP_KV.put("SETUP_COMPLETED", "true"),
233	        env.PAPERCLIP_KV.put("OPERATOR_EMAIL", data.operatorEmail),
234	      ];
235	
236	      if (data.anthropicApiKey) {
237	        kvWrites.push(env.PAPERCLIP_KV.put("ANTHROPIC_API_KEY", data.anthropicApiKey));
238	      }
239	      if (data.openaiApiKey) {
240	        kvWrites.push(env.PAPERCLIP_KV.put("OPENAI_API_KEY", data.openaiApiKey));
241	      }
242	      if (data.sandboxBridgeUrl) {
243	        kvWrites.push(env.PAPERCLIP_KV.put("SANDBOX_BRIDGE_URL", data.sandboxBridgeUrl));
244	      }
245	      if (data.sandboxBridgeApiKey) {
246	        kvWrites.push(env.PAPERCLIP_KV.put("SANDBOX_BRIDGE_API_KEY", data.sandboxBridgeApiKey));
247	      }
248	
249	      // The operator password and Neon connection string are more sensitive —
250	      // in production these should be written via `wrangler secret put` or
251	      // stored encrypted in the DB after the first DB connection is available.
252	      // For the initial setup flow we store them in KV as a bootstrap mechanism;
253	      // the server will read them on first boot and migrate them to encrypted
254	      // DB storage.
255	      // TODO: implement encrypted-in-DB migration once the Hyperdrive driver
256	      // is wired up in boot.ts.
257	      kvWrites.push(env.PAPERCLIP_KV.put("BOOTSTRAP_OPERATOR_PASSWORD", data.operatorPassword));
258	
259	      await Promise.all(kvWrites);
260	    } catch (err) {
261	      const message = err instanceof Error ? err.message : String(err);
262	      return c.html(
263	        setupHtml({
264	          errors: { _global: `Failed to save configuration: ${message}` },
265	          prefill: { ...data, operatorPassword: "" },
266	        }),
267	        500,
268	      );
269	    }
270	
271	    return c.html(setupHtml({ success: true }));
272	  });
273	
274	  return setup;
275	}
